contracts/CryptaCoreRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract CryptaCoreRegistry {
    address public owner;
    mapping(bytes32 => Record) public records;
    uint256 public recordCount;

    struct Record {
        bytes32 recordHash;
        address issuer;
        address recordOwner;
        uint256 timestamp;
        string recordType;
        string ipfsHash;
        uint256 blockNumber;
        bool isValid;
    }

    event RecordRegistered(
        bytes32 indexed recordHash,
        address indexed issuer,
        address indexed recordOwner,
        string recordType,
        uint256 timestamp
    );

    event RecordVerified(
        bytes32 indexed recordHash,
        address indexed verifier,
        bool isValid,
        uint256 timestamp
    );

    constructor() {
        owner = msg.sender;
    }

    function registerRecord(
        bytes32 _recordHash,
        address _recordOwner,
        string memory _recordType,
        string memory _ipfsHash
    ) public returns (bool success) {
        require(_recordHash != bytes32(0), 'Invalid record hash');
        require(_recordOwner != address(0), 'Invalid owner');
        require(!records[_recordHash].isValid, 'Record already exists');

        records[_recordHash] = Record({
            recordHash: _recordHash,
            issuer: msg.sender,
            recordOwner: _recordOwner,
            timestamp: block.timestamp,
            recordType: _recordType,
            ipfsHash: _ipfsHash,
            blockNumber: block.number,
            isValid: true
        });

        recordCount++;

        emit RecordRegistered(
            _recordHash,
            msg.sender,
            _recordOwner,
            _recordType,
            block.timestamp
        );

        return true;
    }

    function verifyRecord(bytes32 _recordHash)
        public
        view
        returns (bool isValid)
    {
        return records[_recordHash].isValid;
    }
}

